package com.parcelproof;
import org.springframework.boot.*;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.math.*;import java.time.*;import java.util.*;
@Configuration class DataInitializer{@Bean CommandLineRunner seed(UserRepo users,PasswordEncoder enc,ParcelService svc){return args->{if(users.count()>0)return;AppUser admin=user("Parcel Admin","admin@example.com","Admin12345",UserRole.ADMIN,enc);AppUser disp=user("Demo Dispatcher","dispatcher@example.com","Dispatcher12345",UserRole.DISPATCHER,enc);AppUser driver=user("Demo Driver","driver@example.com","Driver12345",UserRole.DRIVER,enc);driver.vehicleNumber="WP-CAB-4589";driver.vehicleType=VehicleType.VAN;driver.availabilityStatus=AvailabilityStatus.AVAILABLE;AppUser cust=user("Demo Customer","customer@example.com","Customer12345",UserRole.CUSTOMER,enc);cust.address="45 Main Street, Colombo";cust.customerType=CustomerType.INDIVIDUAL;users.saveAll(List.of(admin,disp,driver,cust));for(int i=1;i<=12;i++){svc.create(new ParcelRequest("Sender "+i,"0711111"+String.format("%03d",i),"Sender Address "+i,"Receiver "+i,"0722222"+String.format("%03d",i),"Receiver Address "+i,i%2==0?"Colombo":"Kandy",i%3==0?ParcelType.DOCUMENT:ParcelType.SMALL_PACKAGE,BigDecimal.valueOf(1+i),BigDecimal.valueOf(350+i*50),i%2==0?PaymentStatus.PAID:PaymentStatus.CASH_ON_DELIVERY,i%4==0?ParcelPriority.EXPRESS:ParcelPriority.NORMAL,cust.id,LocalDate.now(),LocalDate.now().plusDays(i%5+1)),disp);}var all=svc.list(disp);if(all.size()>=3){svc.assign(all.get(0).id(),driver.id,disp);svc.assign(all.get(1).id(),driver.id,disp);svc.assign(all.get(2).id(),driver.id,disp);}};}AppUser user(String n,String e,String p,UserRole r,PasswordEncoder enc){AppUser u=new AppUser();u.fullName=n;u.email=e;u.password=enc.encode(p);u.role=r;u.status=UserStatus.ACTIVE;u.phone="0770000000";return u;}}
@RestControllerAdvice class Errors{@ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Object>> err(Exception e){return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(ApiResponse.fail(e.getMessage()));}}
